    window.THIRTEEN_COLONIES_FACTS = {"massachusetts": "New England Colonies. Founded at Plymouth (1620) and Massachusetts Bay (1630) by Puritans and Pilgrims. Maine was part of it until 1820.", "new-hampshire": "New England Colonies. Founded in 1623. Its people lived by fishing, lumber and shipbuilding.", "connecticut": "New England Colonies. Founded in 1636 by Puritans who moved from Massachusetts.", "rhode-island": "New England Colonies. Founded in 1636 by Roger Williams after Massachusetts forced him out over religion.", "new-york": "Middle Colonies. Began as the Dutch colony of New Netherland. England took it in 1664.", "new-jersey": "Middle Colonies. Taken from the Dutch by England in 1664.", "pennsylvania": "Middle Colonies. Founded in 1681 by William Penn, a Quaker, who promised religious freedom.", "delaware": "Middle Colonies. Settled by Swedes in 1638, then ruled by the Dutch, then by England from 1664.", "maryland": "Southern Colonies. Founded in 1634 as a place where English Catholics could worship freely.", "virginia": "Southern Colonies. Jamestown, founded in 1607, was the first lasting English colony. Tobacco grown by enslaved and indentured workers made it rich.", "north-carolina": "Southern Colonies. Part of the Carolina colony chartered in 1663. It became a separate colony in 1712.", "south-carolina": "Southern Colonies. Charles Town was founded in 1670. Enslaved Africans grew its rice and indigo.", "georgia": "Southern Colonies. Founded in 1733 by James Oglethorpe, the last of the thirteen colonies."};
